const parseDependencies = (jsonSchema: JsonSchema.Object): Predicate.Schema[] => {
	const requiredEntries: [trigger: string, dependencies: string[]][] = []
	const schemaEntries: [trigger: string, schema: Type][] = []
	if ("dependencies" in jsonSchema) {
		for (const [trigger, dependency] of Object.entries(jsonSchema.dependencies)) {
			if (Array.isArray(dependency) && dependency.every(item => typeof item === "string"))
				requiredEntries.push([trigger, dependency])
			else schemaEntries.push([trigger, jsonSchemaToType(dependency)])
		}
	}
	if ("dependentRequired" in jsonSchema)
		for (const [trigger, dependencies] of Object.entries(jsonSchema.dependentRequired))
			requiredEntries.push([trigger, dependencies])
	if ("dependentSchemas" in jsonSchema)
		for (const [trigger, schema] of Object.entries(jsonSchema.dependentSchemas))
			schemaEntries.push([trigger, jsonSchemaToType(schema)])

	const predicates: Predicate.Schema[] = []
	if (requiredEntries.length) {
		const jsonSchemaObjectDependentRequiredValidator = (data: object, ctx: Traversal) => {
			for (const [trigger, dependencies] of requiredEntries) {
				if (!hasOwnKey(data, trigger)) continue
				for (const dependency of dependencies) {
					if (!hasOwnKey(data, dependency)) {
						ctx.reject({
							expected: `an object with the key "${dependency}" (since the key "${trigger}" is present)`,
							actual: printable(data)  — hmm, or `an object missing the key "..."`? printable(data) huge? Follow additionalProperties style: actual: printable(value)... For object-level: printable(data) consistent with min/max? They use counts. Let me use actual: printable(data)? Hmm — maxProperties uses actual counts. I'll do actual: printable(data).
						})
					}
				}
			}
			return !ctx.hasError()
		}
		predicates.push(jsonSchemaObjectDependentRequiredValidator)
	}
	if (schemaEntries.length) {
		const jsonSchemaObjectDependentSchemasValidator = (data: object, ctx: Traversal) => {
			for (const [trigger, schema] of schemaEntries) {
				if (hasOwnKey(data, trigger) && !schema.allows(data)) {
