export const innerParseJsonSchema = JsonSchemaScope.Schema.pipe(
	(jsonSchema: JsonSchemaOrBoolean): type.Any => {
		if (typeof jsonSchema === "boolean") return jsonSchema ? JsonSchemaScope.Json : type.never
		if (Array.isArray(jsonSchema)) return parseAnyOfJsonSchema(jsonSchema)

		if ("$ref" in jsonSchema) return parseJsonSchemaRef(jsonSchema.$ref)

		const constAndOrEnumValidator = parseCommonJsonSchema(jsonSchema as JsonSchema)
		const compositionValidator = parseCompositionJsonSchema(jsonSchema as JsonSchema)
		const conditionalValidator = parseConditionalJsonSchema(jsonSchema as JsonSchema)

		let preTypeValidator = combine([constAndOrEnumValidator, compositionValidator, conditionalValidator])  // .and chain

		if ("type" in jsonSchema) {
			const typeValidator = jsonSchemaTypeMatcher(...)
			if (typeValidator === undefined) throwParseError(unsupported type)
			return preTypeValidator ? typeValidator.and(preTypeValidator) : typeValidator
		}

		if (hasImplicitObjectKeywords(jsonSchema)) {
			const objectValidator = parseObjectJsonSchema.assert({ ...jsonSchema, type: "object" }) as type.Any
			return preTypeValidator ? objectValidator.and(preTypeValidator) : objectValidator
		}

		if (preTypeValidator === undefined) throwParseError(insufficient keys...)
		return preTypeValidator
	}
)
