cat > /app/ark/json-schema/scratch3.scratch.ts <<'EOF'
import { jsonSchemaToType } from "@ark/json-schema"

const check = (label: string, actual: unknown, expected: unknown) => {
	const ok = actual === expected
	console.log(`${ok ? "PASS" : "FAIL"} ${label}: ${JSON.stringify(actual)} (expected ${JSON.stringify(expected)})`)
}

// 1. dependentRequired
const t1 = jsonSchemaToType({
	type: "object",
	dependentRequired: { credit_card: ["billing_address"] }
})
check("dependentRequired {} ok", t1.allows({}), true)
check("dependentRequired trigger w/o dep", t1.allows({ credit_card: 1 }), false)
check("dependentRequired trigger w/ dep", t1.allows({ credit_card: 1, billing_address: "x" }), true)
check("dependentRequired dep alone", t1.allows({ billing_address: "x" }), true)

// 2. dependentSchemas (value without type -> implicit object)
const t2 = jsonSchemaToType({
	type: "object",
	dependentSchemas: {
		credit_card: { properties: { billing_address: { type: "string" } }, required: ["billing_address"] }
	}
})
check("dependentSchemas {} ok", t2.allows({}), true)
check("dependentSchemas trigger invalid", t2.allows({ credit_card: 1 }), false)
check("dependentSchemas trigger valid", t2.allows({ credit_card: 1, billing_address: "x" }), true)

// 3. dependencies both forms
const t3 = jsonSchemaToType({
	type: "object",
	dependencies: {
		a: ["b"],
		c: { properties: { d: { type: "number" } }, required: ["d"] }
	}
})
check("dependencies {} ok", t3.allows({}), true)
check("dependencies a w/o b", t3.allows({ a: 1 }), false)
check("dependencies a w/ b", t3.allows({ a: 1, b: 2 }), true)
check("dependencies c invalid", t3.allows({ c: 1 }), false)
check("dependencies c valid", t3.allows({ c: 1, d: 2 }), true)

// 4. $ref basic
const t4 = jsonSchemaToType({
	$defs: { name: { type: "string" } },
	type: "object",
	properties: { name: { $ref: "#/$defs/name" } }
})
check("$ref basic valid", t4.allows({ name: "foo" }), true)
check("$ref basic invalid", t4.allows({ name: 5 }), false)

// 5. $ref recursion
const t5 = jsonSchemaToType({
	$defs: {
		node: {
			type: "object",
			properties: { value: { type: "string" }, next: { $ref: "#/$defs/node" } },
			required: ["value"]
		}
	},
	$ref: "#/$defs/node"
})
check("recursion depth1", t5.allows({ value: "a" }), true)
check("recursion depth2 ok", t5.allows({ value: "a", next: { value: "b" } }), true)
check("recursion depth2 bad", t5.allows({ value: "a", next: { value: 5 } }), false)
check("recursion depth3 bad", t5.allows({ value: "a", next: { value: "b", next: { value: 5 } } }), false)

// 6. recursion via anyOf
const t6 = jsonSchemaToType({
	$defs: {
		tree: {
			anyOf: [{ type: "string" }, { type: "array", items: { $ref: "#/$defs/tree" } }]
		}
	},
	$ref: "#/$defs/tree"
})
check("tree string", t6.allows("foo"), true)
check("tree nested", t6.allows(["foo", ["bar", []]]), true)
check("tree bad", t6.allows([5]), false)

// 7. mutual recursion
const t7 = jsonSchemaToType({
	$defs: {
		a: { type: "object", properties: { b: { $ref: "#/$defs/b" } } },
		b: { type: "object", properties: { a: { $ref: "#/$defs/a" } } }
	},
	$ref: "#/$defs/a"
})
check("mutual base", t7.allows({}), true)
check("mutual b", t7.allows({ b: {} }), true)
check("mutual b.a", t7.allows({ b: { a: {} } }), true)
check("mutual bad", t7.allows({ b: { a: 5 } }), false)

// 8. ref errors
try { jsonSchemaToType({ $ref: "#/definitions/foo" } as never) } catch (e: any) { console.log("ref format error:", e.message) }
try { jsonSchemaToType({ $ref: "#/$defs/NonExistentDef" }) } catch (e: any) { console.log("ref resolve error:", e.message) }

// 9. enum deep equality
const t9 = jsonSchemaToType({ enum: [{ foo: "bar" }, [1, 2], "baz", 5, null] })
check("enum object deep-eq", t9.allows({ foo: "bar" }), true)
check("enum array deep-eq", t9.allows([1, 2]), true)
check("enum primitive", t9.allows("baz"), true)
check("enum primitive2", t9.allows(5), true)
check("enum null", t9.allows(null), true)
check("enum object not-eq", t9.allows({ foo: "baz" }), false)
check("enum array order", t9.allows([2, 1]), false)
check("enum other", t9.allows("nope"), false)

// 10. const deep equality
const t10 = jsonSchemaToType({ const: { foo: [1, { bar: 2 }] } })
check("const deep-eq", t10.allows({ foo: [1, { bar: 2 }] }), true)
check("const not-eq", t10.allows({ foo: [1, { bar: 3 }] }), false)

// 11. if/then/else
const t11 = jsonSchemaToType({
	type: "object",
	properties: { country: { type: "string" }, postal_code: { type: "string" } },
	if: { properties: { country: { const: "usa" } }, required: ["country"] },
	then: { properties: { postal_code: { type: "string", pattern: "^[0-9]{5}$" } } },
	else: { properties: { postal_code: { type: "string", pattern: "^[A-Z]" } } }
})
check("if/then match-then-ok", t11.allows({ country: "usa", postal_code: "12345" }), true)
check("if/then match-then-bad", t11.allows({ country: "usa", postal_code: "ABC" }), false)
check("if/else nomatch-else-ok", t11.allows({ country: "canada", postal_code: "A1B" }), true)
check("if/else nomatch-else-bad", t11.allows({ country: "canada", postal_code: "123" }), false)

// 12. if alone no-op
const t12 = jsonSchemaToType({ if: { type: "string" } })
check("if alone allows string", t12.allows("foo"), true)
check("if alone allows number", t12.allows(5), true)

// 13. then without if ignored
const t13 = jsonSchemaToType({ then: { type: "string" } })
check("then w/o if allows number", t13.allows(5), true)

// 14. boolean if
const t14 = jsonSchemaToType({ if: true, then: { type: "string" } })
check("if:true then applies", t14.allows("x"), true)
check("if:true then rejects", t14.allows(5), false)
const t14b = jsonSchemaToType({ if: false, then: { type: "string" }, else: { type: "number" } })
check("if:false else applies", t14b.allows(5), true)
check("if:false else rejects", t14b.allows("x"), false)

// 15. chained via allOf
const t15 = jsonSchemaToType({
	type: "object",
	allOf: [
		{ if: { required: ["a"] }, then: { required: ["b"] } },
		{ if: { required: ["c"] }, then: { required: ["d"] } }
	]
})
check("chain none", t15.allows({}), true)
check("chain a->b ok", t15.allows({ a: 1, b: 2 }), true)
check("chain a->b bad", t15.allows({ a: 1 }), false)
check("chain both ok", t15.allows({ a: 1, b: 2, c: 3, d: 4 }), true)
check("chain c->d bad", t15.allows({ a: 1, b: 2, c: 3 }), false)

// 16. $ref in dependentSchemas
const t16 = jsonSchemaToType({
	$defs: { needsB: { required: ["b"] } },
	type: "object",
	dependentSchemas: { a: { $ref: "#/$defs/needsB" } }
})
check("ref in depSchemas no trigger", t16.allows({}), true)
check("ref in depSchemas bad", t16.allows({ a: 1 }), false)
check("ref in depSchemas ok", t16.allows({ a: 1, b: 2 }), true)

// 17. $ref in if/then/else
const t17 = jsonSchemaToType({
	$defs: { str: { type: "string" }, shortStr: { type: "string", maxLength: 3 } },
	if: { $ref: "#/$defs/str" },
	then: { $ref: "#/$defs/shortStr" }
})
check("ref if/then str ok", t17.allows("abc"), true)
check("ref if/then str bad", t17.allows("abcdef"), false)
check("ref if/then non-str", t17.allows(12345), true)

// 18. implicit object schema
const t18 = jsonSchemaToType({ properties: { foo: { type: "string" } }, required: ["foo"] })
check("implicit object ok", t18.allows({ foo: "bar" }), true)
check("implicit object missing", t18.allows({}), false)
check("implicit object non-object", t18.allows("str"), false)

// 19. $defs only used via dependentSchemas at root + nested $ref
const t19 = jsonSchemaToType({
	$defs: { positive: { type: "number", minimum: 0 } },
	type: "object",
	properties: { age: { $ref: "#/$defs/positive" } }
})
check("nested ref ok", t19.allows({ age: 5 }), true)
check("nested ref bad", t19.allows({ age: -5 }), false)
EOF
